/**
 * Curated MITRE ATT&CK Enterprise data: every technique the platform's content
 * cites (lessons, rooms, scenarios, live feed, native log modules) plus useful
 * parents. This is intentionally a working subset (not the full ~600
 * techniques) but is faithful to MITRE tactic names and technique IDs as of
 * ATT&CK v19 (April 2026), which split Defense Evasion into Stealth (TA0005)
 * and Defense Impairment (TA0112). See docs/mitre-attack-v19-mapping.md.
 * Names are the attack.mitre.org page headings ("Parent: Sub" for
 * sub-techniques). `tactic` is the earliest of the technique's tactics in
 * matrix order; `tactics` lists them all when there is more than one.
 * Two Mobile-matrix techniques (T1660, T1626) are included for the MDM
 * scenario, under the Mobile tactic IDs.
 */

export type MitreTactic = {
  id: string;        // TA0001
  name: string;
  short: string;     // for compact UI badges
  description: string;
};

export type MitreTechnique = {
  id: string;        // T1059, T1059.001
  name: string;
  tactic: string;    // tactic id (TA000x)
  tactics?: string[]; // many techniques span multiple tactics
  description: string;
  // Cloud = IaaS, SaaS includes Office Suite, Identity = Identity Provider, Network = Network Devices, PRE = pre-compromise.
  platforms: ("Windows" | "macOS" | "Linux" | "Cloud" | "SaaS" | "Identity" | "Network" | "Containers" | "ESXi" | "PRE" | "Android" | "iOS")[];
  data_sources: string[];
  detection_hint?: string;
  whatAttackerDoes?: string;
  logIndicators?: string[];
};

